content:
[
  {
    "tool": "read_file",
    "arguments": {
      "path": "config.yaml"
    }
  },
  {
    "tool": "execute",
    "arguments": {
      "command": "ping -c 4 <database.host value from config.yaml>"
    }
  },
  {
    "tool": "write_file",
    "arguments": {
      "path": "health-check.txt",
      "content": "<current timestamp>\\nHost: <database.host value from config.yaml>\\n\\n<ping command output>"
    }
  }
]
